('volare_mbj1166_a6_407tca_v1','engine_air','Elemento de seguranca do filtro de ar','elemento secundario do filtro de ar','Tecfil','Dentro do conjunto do filtro de ar','Protege o motor caso o elemento principal seja danificado','ASR203','https://catalogo.tecfil.com.br/?pagina=5'),
('mb608_byh8j61_om314_v1','engine_air','Elemento de seguranca do filtro de ar','elemento secundario do filtro de ar','MANN-FILTER','Dentro do conjunto do filtro de ar','Protege o motor caso o elemento principal seja danificado','CF 600','https://www.mann-filter.com/br-pt/catalogo/resultados-da-pesquisa/produto.suffix.html/cf600_mann-filter.html')
)
insert into public.v2_vehicle_components(group_code,name,generic_name,oem_brand,manufacturer_part_number,location_description,function_description,data_status,source_metadata,component_type,service_priority)
select e.group_code,e.name,e.generic_name,e.brand,e.part_number,e.location_description,e.function_description,'reference_pending',
 jsonb_build_object('seed',e.seed,'oem_code_verified',false,'physical_fitment_verified',false,'source_url',e.source_url,'reference_level','direct_application_catalog'),
 'part','medium'
from extras e
where not exists(select 1 from public.v2_vehicle_components c where c.source_metadata->>'seed'=e.seed and c.name=e.name);

with map(seed,plate,chassis_family,chassis_variant,engine_family,engine_code,yf,yt) as (values
('comil_cpi6c79_vw9150_mwm412_v1','CPI6C79','Volkswagen 9.150 EOD','Comil Pia O / chassis 9BWD252R25R527468','MWM Acteon Serie 12','4.12 TCE',2004,2012),
('volare_mbj1166_a6_407tca_v1','MBJ1166','Marcopolo Volare','A6 131 cv / chassis 93PB03A2MYC002968','MWM Sprint','4.07 TCA',1999,2002),
('mb608_byh8j61_om314_v1','BYH8J61','Mercedes-Benz 608','LO 608 candidato / chassis 30830311268441','Mercedes-Benz','OM314',1973,1988)
)
insert into public.v2_vehicle_component_applications(component_id,chassis_family,chassis_variant,engine_family,engine_code,model_year_from,model_year_to,notes,fitment_status,source_metadata)
select c.id,m.chassis_family,m.chassis_variant,m.engine_family,m.engine_code,m.yf,m.yt,
 'Aplicacao direta por familia/ano em catalogo de filtros; confirmar montagem fisica antes da compra.','candidate',
 jsonb_build_object('vehicle_plate_reference',m.plate,'physical_confirmation_required',true)
from map m join public.v2_vehicle_components c on c.source_metadata->>'seed'=m.seed
where c.name like 'Elemento%filtro de ar%'
 and not exists(select 1 from public.v2_vehicle_component_applications a where a.component_id=c.id and a.chassis_variant=m.chassis_variant);

with map(seed,plate) as (values
('comil_cpi6c79_vw9150_mwm412_v1','CPI6C79'),('volare_mbj1166_a6_407tca_v1','MBJ1166'),('mb608_byh8j61_om314_v1','BYH8J61'))
insert into public.v2_vehicle_component_links(company_id,vehicle_id,component_id,fitment_status,notes)
select v.company_id,v.id,c.id,'candidate','Aplicacao de catalogo confirmada para a familia; conferir peca instalada antes da compra.'
from map m join public.v2_vehicles v on upper(replace(coalesce(v.plate,''),'-',''))=m.plate
join public.v2_vehicle_components c on c.source_metadata->>'seed'=m.seed and c.name like 'Elemento%filtro de ar%'
on conflict(company_id,vehicle_id,component_id) do nothing;

