update public.v2_vehicle_components set manufacturer_part_number='Tecfil PSL340',dimensions_spec=jsonb_build_object('height_mm',93,'outer_diameter_mm',138),thread_spec=jsonb_build_object('thread','1 1/2-16 UN'),source_metadata=source_metadata||jsonb_build_object('direct_catalog_match',true,'alternate_refs',jsonb_build_array('MANN W 1323'),'source_url','https://catalogo.tecfil.com.br/?pagina=5') where source_metadata->>'seed'='volare_mbj1166_a6_407tca_v1' and name='Filtro de oleo';
