update public.v2_vehicle_components set manufacturer_part_number='MANN BFU 707',source_metadata=source_metadata||jsonb_build_object('direct_catalog_match',true,'alternate_refs',jsonb_build_array('Tecfil PSD530/1','Tecfil PSD530','Tecfil CSD01'),'source_url','https://www.mann-filter.com/br-pt/catalogo/resultados-da-pesquisa/produto.html/bfu707_mann-filter.html') where source_metadata->>'seed'='mb608_byh8j61_om314_v1' and name='Pre-filtro de combustivel';

update public.v2_vehicle_components c set
 failure_symptoms=case c.group_code when 'engine' then jsonb_build_array('ruido mecanico anormal','baixa potencia ou compressao','consumo de oleo/fumaca/vazamento') when 'engine_air' then jsonb_build_array('perda de potencia','fumaca preta','restricao de admissao ou entrada de poeira') when 'engine_turbo' then jsonb_build_array('perda de potencia','assobio anormal','fumaca e/ou oleo na admissao') when 'engine_fuel' then jsonb_build_array('dificuldade de partida','falha/perda de potencia','fumaca ou consumo irregular') when 'engine_cooling' then jsonb_build_array('superaquecimento','perda de liquido','temperatura instavel') when 'engine_lubrication' then jsonb_build_array('baixa pressao de oleo','vazamento','ruido por falta de lubrificacao') when 'exhaust' then jsonb_build_array('ruido excessivo','fumaca/vazamento de gases','freio motor inoperante quando aplicavel') when 'transmission' then jsonb_build_array('dificuldade de engate','patinacao/trepidacao','ruido ou vazamento') when 'driveline' then jsonb_build_array('vibracao em movimento','estalos/folga','ruido de diferencial ou cardan') when 'brakes' then jsonb_build_array('frenagem fraca ou desigual','vazamento/perda de pressao','ruido ou superaquecimento') when 'steering' then jsonb_build_array('folga excessiva','direcao pesada','vazamento/ruido quando hidraulica') when 'suspension' then jsonb_build_array('batidas','inclinacao/desgaste irregular','instabilidade') when 'electrical' then jsonb_build_array('nao funciona/intermitente','tensao fora do esperado','falha de partida/carga ou sinal') when 'body' then jsonb_build_array('folga/quebra','infiltracao ou desalinhamento','falha de abertura/iluminacao') when 'hvac' then jsonb_build_array('nao refrigera','ruido','vazamento de refrigerante') else jsonb_build_array('falha funcional','ruido ou vazamento','desgaste') end,
 diagnostic_notes=case c.group_code when 'engine' then jsonb_build_array('Confirmar sintomas antes da desmontagem; medir compressao/pressao de oleo/folgas conforme o componente.','Comparar medidas e limites com manual do motor da variante instalada.','Nao promover codigo ou torque sem manual/plaqueta/medida fisica.') when 'engine_air' then jsonb_build_array('Inspecionar elemento, vedacoes e dutos contra poeira, colapso e entradas falsas.','Medir restricao/pressao quando aplicavel e testar estanqueidade do circuito.','Substituir elemento se contaminado ou danificado; nao limpar elemento de seguranca para reutilizacao.') when 'engine_turbo' then jsonb_build_array('Inspecionar mangueiras/intercooler antes de condenar o turbo.','Verificar folga do eixo, sinais de oleo e pressao de sobrealimentacao conforme manual.','Nao tocar em partes quentes nem operar com dutos removidos.') when 'engine_fuel' then jsonb_build_array('Comecar por contaminacao, filtros, entrada de ar e alimentacao antes de bomba/injetores.','Em common rail, usar scanner e pressao especificada; nunca afrouxar linha de alta com sistema pressurizado.','Em sistema mecanico, conferir ponto, retorno, estanqueidade e codigo fisico da bomba/bicos.') when 'engine_cooling' then jsonb_build_array('Fazer teste de pressao somente com sistema frio e ferramenta adequada.','Conferir vazamentos, tampa, mangueiras, termostato, bomba e fluxo do radiador.','Superaquecimento recorrente exige investigar gases de combustao e obstrucao antes de trocar pecas aleatoriamente.') when 'engine_lubrication' then jsonb_build_array('Confirmar nivel/viscosidade/filtro e medir pressao com manometro antes de abrir o motor.','Vazamento deve ser localizado apos limpeza; nao confundir escorrimento de outra origem.','Baixa pressao real exige interromper o uso ate diagnostico.') when 'exhaust' then jsonb_build_array('Inspecionar juntas, trincas, suportes e contrapressao.','No freio motor, conferir atuacao pneumatica/eletrica e movimento da borboleta com motor desligado quando possivel.') when 'transmission' then jsonb_build_array('Conferir nivel/estado do lubrificante, regulagem do acionamento e trambulador antes de abrir a caixa.','Folga, ruido e dificuldade de engate devem ser relacionados a marcha/carga/temperatura.','Torque e folgas internas exigem manual da caixa efetivamente instalada.') when 'driveline' then jsonb_build_array('Verificar folga de cruzetas, mancal, estriados e angulos do cardan.','Marcar posicao antes de desmontar cardan para preservar balanceamento.','Ruido do diferencial exige conferir oleo, folga e rolamentos antes de ajuste interno.') when 'brakes' then jsonb_build_array('Sistema de freio e item critico: imobilizar o veiculo se houver perda de pressao, fluido ou frenagem desigual.','Medir espessura/diametro/folgas e testar atuadores; nao confiar apenas em inspecao visual.','Usar cavaletes adequados e calcos; nunca trabalhar sob veiculo apoiado apenas no macaco.') when 'steering' then jsonb_build_array('Separar folga de terminal/barra/caixa antes de substituir componentes.','Em sistema hidraulico, verificar nivel, vazamentos, pressao e ar no circuito.','Qualquer travamento ou folga severa deve impedir circulacao ate reparo.') when 'suspension' then jsonb_build_array('Inspecionar molas, buchas, pinos, amortecedores, grampos e pontos de fixacao com veiculo apoiado de forma segura.','Comparar altura dos lados e procurar trincas/deslocamento.','Aperto final de componentes estruturais deve seguir torque do fabricante.') when 'electrical' then jsonb_build_array('Medir tensao e queda de tensao antes de substituir componente.','Confirmar alimentacao, aterramento, fusivel/rele e continuidade do chicote.','Em sensores eletronicos, comparar sinal real com scanner/osciloscopio quando aplicavel.') when 'body' then jsonb_build_array('Inspecionar fixacoes, alinhamento, corrosao e interferencias.','Em iluminacao, confirmar alimentacao e aterramento antes de trocar a peca.') when 'hvac' then jsonb_build_array('Conferir acionamento, correia, pressao e temperatura antes de condenar compressor.','Recuperacao/carga de refrigerante deve usar equipamento proprio; nao liberar gas deliberadamente.') else jsonb_build_array('Confirmar causa antes da substituicao.','Comparar com manual/medida fisica da conducao.') end,
 required_tools=case c.group_code when 'engine' then jsonb_build_array('torquimetro','paquimetro/micrometro','manometro de oleo','compressimetro diesel quando aplicavel') when 'engine_air' then jsonb_build_array('lanterna','chaves/soquetes','medidor de restricao ou manometro quando aplicavel') when 'engine_turbo' then jsonb_build_array('chaves/soquetes','manometro/scan tool quando aplicavel','relogio comparador quando necessario') when 'engine_fuel' then jsonb_build_array('chaves adequadas de combustivel','multimetro','scanner no sistema eletronico','manometro/equipamento de teste apropriado') when 'engine_cooling' then jsonb_build_array('testador de pressao do arrefecimento','termometro infravermelho','chaves/soquetes') when 'engine_lubrication' then jsonb_build_array('manometro de pressao de oleo','chave de filtro','bandeja de drenagem','chaves/soquetes') when 'exhaust' then jsonb_build_array('chaves/soquetes','inspecao visual/lanterna','manometro de contrapressao quando aplicavel') when 'transmission' then jsonb_build_array('torquimetro','macaco de transmissao quando necessario','chaves/soquetes','relogio comparador quando aplicavel') when 'driveline' then jsonb_build_array('cavaletes','torquimetro','relogio comparador','chaves/soquetes') when 'brakes' then jsonb_build_array('cavaletes e calcos','torquimetro','paquimetro/micrometro','manometro de ar ou sangrador conforme sistema') when 'steering' then jsonb_build_array('cavaletes','saca-terminal','torquimetro','manometro hidraulico quando aplicavel') when 'suspension' then jsonb_build_array('cavaletes e macaco adequado','torquimetro','saca-pinos/buchas quando aplicavel') when 'electrical' then jsonb_build_array('multimetro','alicate amperimetro','lampada de teste adequada','scanner/osciloscopio quando aplicavel') when 'hvac' then jsonb_build_array('manifold de A/C','termometro','detector de vazamento','estacao de recolhimento/carga') else jsonb_build_array('chaves/soquetes','torquimetro quando aplicavel') end,
 torque_spec=case when c.torque_spec='{}'::jsonb then jsonb_build_object('status','manual_required','note','Confirmar torque pelo manual/codigo do conjunto instalado antes do aperto; valor nao inferido pelo Oficina 360.') else c.torque_spec end,
 service_priority=case when c.group_code in ('brakes','steering','engine_fuel') then 'high' when c.group_code in ('engine','engine_cooling','engine_lubrication','transmission','driveline','suspension','electrical') then 'medium' else coalesce(c.service_priority,'low') end,
 component_type=case when lower(c.name) like '%sensor%' then 'sensor' when lower(c.name) like '%mangueira%' or lower(c.name) like '%mangote%' then 'hose' when lower(c.name) like '%tubo%' then 'pipe' when lower(c.name) like '%rolamento%' then 'bearing' when lower(c.name) like '%junta%' then 'gasket' when lower(c.name) like '%atuador%' then 'actuator' when lower(c.name) like '%filtro%' or lower(c.name) like '%elemento%' then 'consumable' else coalesce(nullif(c.component_type,''),'part') end,
 replacement_notes=case when c.replacement_notes='[]'::jsonb then jsonb_build_array('Conferir referencia fisica, dimensoes e fornecedor da peca retirada antes da compra.','Registrar no historico do veiculo a marca/codigo realmente instalado apos o servico.') else c.replacement_notes end,updated_at=now()
where c.source_metadata->>'seed' in ('comil_cpi6c79_vw9150_mwm412_v1','volare_mbj1166_a6_407tca_v1','mb608_byh8j61_om314_v1');

with vehicles(seed,plate,chassis_family,chassis_variant,engine_code) as (values
('comil_cpi6c79_vw9150_mwm412_v1','CPI6C79','Volkswagen 9.150 EOD','Comil Pia O / chassis 9BWD252R25R527468','4.12 TCE'),
('volare_mbj1166_a6_407tca_v1','MBJ1166','Marcopolo Volare','A6 131 cv / chassis 93PB03A2MYC002968','4.07 TCA'),
('mb608_byh8j61_om314_v1','BYH8J61','Mercedes-Benz 608','LO 608 candidato / chassis 30830311268441','OM314')
),groups as (select distinct c.source_metadata->>'seed' seed,c.group_code from public.v2_vehicle_components c where c.source_metadata->>'seed' in ('comil_cpi6c79_vw9150_mwm412_v1','volare_mbj1166_a6_407tca_v1','mb608_byh8j61_om314_v1'))
insert into public.v2_vehicle_exploded_views(group_code,chassis_family,chassis_variant,engine_code,assembly_code,title,subtitle,source_name,source_diagram_key,image_license_status,verification_status,notes,source_metadata)
select g.group_code,v.chassis_family,v.chassis_variant,v.engine_code,v.plate||'-'||g.group_code||'-STRUCT-V1',cg.name||' — '||v.plate,'Vista estruturada do Oficina 360: posicoes organizadas por sistema; nao representa desenho OEM em escala.','Oficina 360 / catalogos de aplicacao','STRUCT-'||v.plate||'-'||g.group_code,'generated','estimated','Usar como mapa de componentes e diagnostico. Quantidades/posicoes marcadas como estimadas ate EPC/manual ou conferencia fisica.',jsonb_build_object('seed',v.seed,'plate',v.plate,'generated_catalog',true,'copyright_safe',true)
from groups g join vehicles v on v.seed=g.seed join public.v2_vehicle_component_groups cg on cg.code=g.group_code where not exists(select 1 from public.v2_vehicle_exploded_views ev where ev.assembly_code=v.plate||'-'||g.group_code||'-STRUCT-V1');

with ranked as (select ev.id exploded_view_id,c.id component_id,c.name,c.location_description,c.component_type,row_number() over(partition by ev.id order by c.name,c.id)::text item_number,case when lower(c.name) in ('pistao','biela','bico injetor','injetor common rail','bico injetor mecanico') then 4 when lower(c.name) like '%bateria 12 v%' then 1 when lower(c.name) like '%tubos de alta%' and c.source_metadata->>'seed' in ('volare_mbj1166_a6_407tca_v1','mb608_byh8j61_om314_v1') then 4 else 1 end::numeric quantity from public.v2_vehicle_exploded_views ev join public.v2_vehicle_components c on c.source_metadata->>'seed'=ev.source_metadata->>'seed' and c.group_code=ev.group_code where ev.source_metadata->>'seed' in ('comil_cpi6c79_vw9150_mwm412_v1','volare_mbj1166_a6_407tca_v1','mb608_byh8j61_om314_v1'))
insert into public.v2_vehicle_exploded_view_items(exploded_view_id,component_id,item_number,quantity,component_type,position_note,exactness_status,source_metadata)
select r.exploded_view_id,r.component_id,r.item_number,r.quantity,case when r.component_type in ('assembly','part','fastener','washer','nut','bolt','screw','stud','seal','o_ring','gasket','clip','spring','bearing','bushing','hose','pipe','connector','wire','sensor','actuator','consumable','other') then r.component_type else 'part' end,r.location_description,'estimated',jsonb_build_object('position_basis','alphabetical structured catalog','quantity_basis','estimated service unit','physical_confirmation_required',true) from ranked r where not exists(select 1 from public.v2_vehicle_exploded_view_items i where i.exploded_view_id=r.exploded_view_id and i.component_id=r.component_id);

update public.v2_vehicle_components c set exploded_view_reference=ev.assembly_code,updated_at=now() from public.v2_vehicle_exploded_views ev where c.source_metadata->>'seed'=ev.source_metadata->>'seed' and c.group_code=ev.group_code and c.source_metadata->>'seed' in ('comil_cpi6c79_vw9150_mwm412_v1','volare_mbj1166_a6_407tca_v1','mb608_byh8j61_om314_v1');

insert into public.v2_vehicle_component_relations(parent_component_id,child_component_id,relation_type,quantity,notes,source_metadata)
select p.id,s.id,'contains',1,'Elemento secundario/seguranca dentro do conjunto de filtracao de ar.',jsonb_build_object('catalog','fleet_deep_catalog_v1') from public.v2_vehicle_components p join public.v2_vehicle_components s on s.source_metadata->>'seed'=p.source_metadata->>'seed' where p.source_metadata->>'seed' in ('comil_cpi6c79_vw9150_mwm412_v1','volare_mbj1166_a6_407tca_v1','mb608_byh8j61_om314_v1') and ((p.name='Filtro de ar do motor' and s.name='Elemento secundario do filtro de ar') or (p.name in ('Filtro de ar','Filtro de ar seco') and s.name='Elemento de seguranca do filtro de ar')) on conflict(parent_component_id,child_component_id,relation_type) do nothing;